#!/bin/sh
# Local models and config are generated by package_native_vision.py.
# Metrics only; no PC measurement producer or pixel transport.
set -eu
directory=${1:?usage: run_native.sh absolute-package-directory frames}
frames=${2:-300}
cd "$directory"
directory=$(pwd)
sha256sum -c manifest.sha256
. ./runtime.env
export LD_LIBRARY_PATH="$directory${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
export VIGI_DETECTOR_DIR="$directory" VIGI_LANDMARK_MODEL="$directory/$VG_LANDMARK_FILE"
export VIGI_CAMERA_FORMAT="$VG_CAMERA_FORMAT"
export OMP_WAIT_POLICY=PASSIVE GOMP_SPINCOUNT=0
export VIGI_CONTRACT_LOG="$directory/contracts.jsonl" VIGI_CONTRACT_LATEST="$directory/latest.json"
export VIGI_JPEG_FAST=1 VIGI_PIPELINE=threaded VIGI_DECODE_WORKERS=2 VIGI_PL_WAIT=yield VIGI_AUDIT_EVERY=30
unset VIGI_STREAM_BIND VIGI_VERIFY VIGI_LANDMARK_EVERY VIGI_ERT_SYNC VIGI_TRACKER_SYNC VIGI_ERT_TRACE
http_pid= camera_pid=
cleanup() {
    [ -z "$camera_pid" ] || kill "$camera_pid" 2>/dev/null || true
    [ -z "$http_pid" ] || kill "$http_pid" 2>/dev/null || true
}
trap cleanup 0
trap 'exit 143' HUP INT TERM
./vg_metrics_http --bind "${VIGI_HTTP_BIND:-0.0.0.0}" --port "${VIGI_HTTP_PORT:-8080}" \
    --latest "$directory/latest.json" --display "$directory/display.html" \
    --stale-seconds "$VG_STALE_SECONDS" > "$directory/http.log" 2>&1 &
http_pid=$!
./vigi_camera_autonomy /dev/video0 "$VG_CAPTURE_WIDTH" "$VG_CAPTURE_HEIGHT" "$frames" "$VG_CAPTURE_FPS" "$VG_MOTION_THRESHOLD" \
    > "$directory/camera.log" 2>&1 &
camera_pid=$!
printf 'NATIVE_RUN camera_pid=%s http_pid=%s frames=%s\n' "$camera_pid" "$http_pid" "$frames"
set +e
wait "$camera_pid"
rc=$?
printf 'NATIVE_CAMERA_EXIT=%s\n' "$rc"
exit "$rc"
